CREATE TABLE CUSTMAST (CUSNO TEXT PRIMARY KEY, CUSNM TEXT NOT NULL, CONTACT TEXT, EMAIL TEXT, PHONE TEXT, CRHOLD TEXT, SINCE TEXT, CITY TEXT, CTRY TEXT);
CREATE TABLE ITEMMAST (ID INTEGER PRIMARY KEY, ITMNO TEXT NOT NULL, DESCR TEXT NOT NULL, CATG TEXT, UPRICE TEXT, UOM TEXT, AVAIL_FLG TEXT, DISC_FLG TEXT, UPDTS TEXT);
CREATE TABLE STOCKBAL (ITEM TEXT NOT NULL, WH TEXT NOT NULL, ON_HAND TEXT, ALLOCATED TEXT);
CREATE TABLE ORDHDR (ORDNO TEXT PRIMARY KEY, CUSNO TEXT NOT NULL, ORDDT TEXT, STAT TEXT, TOTAL TEXT, CUSTREF TEXT);
CREATE TABLE ORDLIN (ORDNO TEXT NOT NULL, LN INTEGER NOT NULL, ITEM TEXT NOT NULL, QTY TEXT, UPRICE TEXT, PRIMARY KEY (ORDNO, LN));
